				[4] = {
					1,
					1
				}
			},
			{
				[1.0] = "超级金柳露",
				[3.0] = true,
				[2] = qz1(50 * 等级标准 * 100),
				[4] = {
					5,
					5
				}
			},
			{
				[1.0] = "怪物卡片",
				[3.0] = true,
				[2] = qz1(50 * 等级标准 * 100),
				[4] = {
					6,
					8
				}
			}
		}
	end

	return 活动奖励列表
end

战斗数据标准模板 = function(数据, id, 任务id, 战斗中召唤)
	local 战斗单位 = {
		阵法 = 数据.阵法
	}
	local 等级 = 数据.等级
	local 怪物名称 = 数据.怪物数据

	for n = 1, #怪物名称 do
		战斗单位[n] = {
			名称 = 怪物名称[n].名称,
			模型 = 怪物名称[n].模型,
			气血 = 阶段属性[等级].气血 * 怪物名称[n].气血,
			魔法 = 阶段属性[等级].魔法 * 怪物名称[n].魔法,
			伤害 = 阶段属性[等级].伤害 * 怪物名称[n].伤害,
			灵力 = 阶段属性[等级].法伤 * 怪物名称[n].法伤,
			速度 = 阶段属性[等级].速度 * 怪物名称[n].速度,
			防御 = 阶段属性[等级].防御 * 怪物名称[n].防御,
			法防 = 阶段属性[等级].法防 * 怪物名称[n].法防,
			躲避 = 阶段属性[等级].躲避 * 怪物名称[n].躲避,
			愤怒 = 怪物名称[n].愤怒 or 0,
			等级 = 怪物名称[n].等级 or 等级,
			变异 = 怪物名称[n].变异,
			显示饰品 = 怪物名称[n].显示饰品,
			不可封印 = 怪物名称[n].不可封印,
			角色 = 怪物名称[n].角色,
			技能 = 怪物名称[n].被动技能,
			主动技能 = 怪物名称[n].主动技能,
			攻击修炼 = 阶段属性[等级].修炼 * (怪物名称[n].修炼[1] or 0),
			防御修炼 = 阶段属性[等级].修炼 * (怪物名称[n].修炼[2] or 0),
			法术修炼 = 阶段属性[等级].修炼 * (怪物名称[n].修炼[3] or 0),
			抗法修炼 = 阶段属性[等级].修炼 * (怪物名称[n].修炼[4] or 0),
			指定攻击目标 = 怪物名称[n].指定攻击目标,
			附加状态 = 怪物名称[n].附加状态,
			发言 = 怪物名称[n].发言,
			不攻击 = 怪物名称[n].不攻击,
			特殊标记 = 怪物名称[n].特殊标记,
			召唤物 = 怪物名称[n].召唤物,
			召唤主人 = 怪物名称[n].召唤主人,
			追加法术 = 怪物名称[n].追加法术
		}

		if not 判断是否为空表(怪物名称[n].其他属性 or {}) then
			for k, v in pairs(怪物名称[n].其他属性) do
				战斗单位[n][k] = (战斗单位[n][k] or 1) * v
			end
		end
	end

	if 战斗中召唤 ~= nil then
		return 战斗单位[1]
	end

	return 全局战斗难度调整(战斗单位)
end
